package com.friendinneed.robot;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Service;
@Service @ConditionalOnProperty(name="robot.mode",havingValue="simulated",matchIfMissing=true) public class SimulatedRobot implements RobotHardware{private final RobotWebSocketEndpoint socket;private final RobotProperties props;private volatile double pan,tilt;private volatile String color="#ffffff",pattern="solid";public SimulatedRobot(RobotWebSocketEndpoint s,RobotProperties p){socket=s;props=p;}public void moveHead(double p,double t){pan=Math.clamp(p,props.headPanMin(),props.headPanMax());tilt=Math.clamp(t,props.headTiltMin(),props.headTiltMax());socket.send(Map.of("type","moveHead","pan",pan,"tilt",tilt));}public void setLed(String c,String p){color=c;pattern=p;socket.send(Map.of("type","setLed","color",c,"pattern",p));}public double getDistance(){return socket.distance();}public double getBatteryPercent(){return 100;}public double getTemperature(){return 42;}public byte[] captureImage(){return socket.requestImage();}public void playAudio(byte[] b){socket.send(Map.of("type","playAudio","audioBase64",Base64.getEncoder().encodeToString(b)));}public boolean isTouchActive(String z){return socket.touch(z);}public double pan(){return pan;}public double tilt(){return tilt;}public String color(){return color;}public String pattern(){return pattern;}}
